function i(t){return`<span class="sci-math sci-math--block">${t}</span>`}function c(t){return`<span class="sci-math">${t}</span>`}function r(t){return`<table class="sci-vars"><tbody>${t.map(([s,a])=>`<tr><td>${c(s)}</td><td>${a}</td></tr>`).join("")}</tbody></table>`}function o(t){return`<p class="sci-cite">${t}</p>`}function d(t,s){return`<table class="sci-data"><thead><tr>${t.map(a=>`<th>${a}</th>`).join("")}</tr></thead><tbody>${s.map(a=>`<tr>${a.map(n=>`<td>${n}</td>`).join("")}</tr>`).join("")}</tbody></table>`}function l(t,s,a,n){return`<div class="les-concept"><h3 class="les-concept__name">${t}</h3><div class="les-concept__body">${n==="advanced"?a:s}</div></div>`}function p(t){return`<div class="les-analogy"><span class="les-analogy__icon">&#128161;</span>${t}</div>`}function u(t){return`<div class="les-key-idea"><span class="les-key-idea__icon">&#9733;</span>${t}</div>`}function y(t,s){return`<div class="sci-try"><div class="sci-try__title">${t}</div>${s}</div>`}function $(t,s){return`<div class="sci-try__row">${t}${s}</div>`}function v(t,s){return`<div class="sci-try__output">${s}<span class="sci-try__value" id="${t}"></span></div>`}export{i as a,c as b,r as c,o as d,d as e,l as f,p as g,u as h,y as i,$ as j,v as k};
